// Solo reservas nuevas y SOLO si la persona acepto las cookies en la web.
// Sin metadata.consent = 1 no se manda nada a Meta (lo promete privacy.html).
const out = [];
for (const it of $input.all()) {
  const b = it.json.body || it.json;
  if (b.triggerEvent !== 'BOOKING_CREATED') continue;
  const p = b.payload || {};
  const m = p.metadata || {};
  if (String(m.consent) !== '1') continue;
  const a = (p.attendees || [])[0] || {};
  const r = p.responses || {};
  const email = String(a.email || (r.email && r.email.value) || '').trim().toLowerCase();
  const phone = String((r.attendeePhoneNumber && r.attendeePhoneNumber.value) || a.phoneNumber || '').replace(/\D/g, '');
  out.push({ json: {
    uid: p.uid,
    creado: b.createdAt || new Date().toISOString(),
    email, phone,
    nicho: m.nicho || '', fbp: m.fbp || '', fbc: m.fbc || '', url: m.url || '', ua: m.ua || ''
  }});
}
return out;

// event_id = uid de Cal.com: la web manda el mismo al pixel y Meta deduplica.
// Para probar: pon el codigo de 'Probar eventos' del Administrador de eventos en TEST.
const TEST = '';
return $input.all().map(it => {
  const j = it.json;
  const ud = { em: [j.em] };
  if (j.phone) ud.ph = [j.ph];
  if (j.fbp) ud.fbp = j.fbp;
  if (j.fbc) ud.fbc = j.fbc;
  if (j.ua) ud.client_user_agent = j.ua;
  const body = { data: [{
    event_name: 'Schedule',
    event_time: Math.floor(new Date(j.creado).getTime() / 1000),
    event_id: j.uid,
    action_source: 'website',
    event_source_url: j.url || 'https://easyrobots-ai.cloud/',
    user_data: ud,
    custom_data: { nicho: j.nicho, content_category: j.nicho }
  }]};
  if (TEST) body.test_event_code = TEST;
  return { json: { body } };
});
